\label{thm:FourierSlice} Let $f\in\mathcal{T}'$ and $v\in\mathbb{Z}^2\setminus\{0\}$. The Fourier transform of the X-ray data satisfies
\begin{equation}
    \widehat{\mathcal{I}f}(k,v) = \begin{cases}
\hat{f}(k),&k\cdot v = 0,\\
0,&k\cdot v  \neq 0.
\end{cases}
\end{equation}

\label{thm:inversion}
    Suppose that $f\in L^1(\mathbb{T}^2)$. Let $k\in\mathbb{Z}^2$. If $k\neq 0$ and $v\in\mathbb{Z}^2\setminus\{0\}$ satisfies $v\perp k$, then
    \begin{equation}
        \hat{f}(k)=\begin{cases}
            \int_0^1\mathcal{I}_v f(0,y)\exp{(-2\pi i k_2 y)}~dy, & k_2\neq 0,\\
            \int_0^1\mathcal{I}_v f(x,0)\exp{(-2\pi i k_1 x)}~dx, & k_1\neq 0.
        \end{cases}
    \end{equation}
    If $k=0$, then
    \begin{equation}
        \label{eq:mean}\hat{f}(0)=\int_0^1\mathcal{I}_{(1,0)}f(0,y)~dy=\int_0^1\mathcal{I}_{(0,1)}f(x,0)~dx.
    \end{equation}

\label{thm:TBP}Let $f\in \mathcal{T}'$ with $\hat{f}(0)=0$. Then \begin{equation}
    f = \sum_{v\in Q} \mathcal{I}_v f,
\end{equation}
where sum is taken over all primitive integer directions $v\in Q$ and $\mathcal{I}_vf:=\mathcal{I}f(\cdot,v)$ denotes the X-ray data in direction $v$.

\label{prop:f_N_convergence}
    Let $f\in\mathcal{T}'$. Then $f_N$ converges to $f$ in the sense of distributions, i.e.,
    \begin{equation}
        \lim_{N\rightarrow \infty} f_N = f \quad \text{in } \mathcal{T'}.
    \end{equation}
    Moreover, if $f\in H^t(\mathbb{T}^2)$ for some $t\in \mathbb{R}$, then $f_N\rightarrow f$ in $H^t(\mathbb{T}^2)$.

By the Fourier slice theorem~\ref{thm:FourierSlice}, it holds that 
\begin{equation}
    \mathcal{I}_vf(x) = \sum_{v \cdot k=0, \,k \in \mathbb{Z} ^2} \hat{f}(k)e^{2\pi i k \cdot x}
\end{equation}
for any $v \in \mathbb{Z}^2 \setminus \{0\}$, in the sense of distributions, with a slight abuse of notation. Furthermore, from the fact $f \in \mathcal{T}'$, one notices that $\mathcal{I}_vf \in \mathcal{T}'$ for any $v \in \mathbb{Z}^2 \setminus \{0\}$. Since $Q_N$ is a finite set, it follows that $f_N \in \mathcal{T}'$ as a finite sum of distributions for any $N \in \mathbb{N}$.

Let now $k \in \mathbb{Z}^2 \setminus \{0\}$. We show that there exists $N_k \geq 0$ such that for any $N \geq N_k$ it holds that $\hat{f}_N(k)=\hat{f}(k)$. It follows from the definition of $Q_N$ that for any $N \geq |k|_\infty$ there exists $v \in Q_N$ such that $v \cdot k = 0$. One may now compute, using the Fourier slice theorem~\ref{thm:FourierSlice} and the definition of $f_N$, that $\hat{f}_N(k)=\hat{f}(k)$ for any $N \geq N_k := |k|_{\infty}$. On the other hand, one can compute that 
\begin{equation}
    \hat{f}_N(0) = \sum_{v \in Q_N} (\widehat{\mathcal{I}_vf}(0) - \frac{|Q_N|-1}{|Q_N|}\hat{f}(0)) = \sum_{v \in Q_N} (\hat{f}(0) - \frac{|Q_N|-1}{|Q_N|}\hat{f}(0)) = \hat{f}(0)
\end{equation}
for any $N \in \mathbb{N}$. In particular, $\hat{f}_N(k) = \hat{f}(k)$ for all $k\in\mathbb{Z}^2_N$.

Since $f\in\mathcal{T}'$, there exists $t\in\mathbb{R}$ such that $f\in H^t(\mathbb{T}^2)$. For $\xi\neq 0$, at most one $v\in Q_N$ is orthogonal to $\xi$, so $\hat{f}_N(\xi)$ attains either value $\hat{f}(\xi)$ or zero. We can now estimate
\begin{align}
    \| f_{N} - f \|^2_{H^t(\mathbb{T}^2)} &= \sum _{\xi \in \mathbb{Z}^2} \langle  \xi\rangle^{2t} | (\hat{f}_{N} - \hat{f})(\xi)|^2 = \sum_{\xi\in\mathbb{Z}^2\setminus \mathbb{Z}^2_{N}} \langle  \xi\rangle^{2t} | (\hat{f}_{N} - \hat{f})(\xi)|^2\\ &\leq \sum_{\xi\in\mathbb{Z}^2\setminus \mathbb{Z}^2_{N}} \langle  \xi\rangle^{2t} | \hat{f}(\xi)|^2 \rightarrow 0, \quad \text{as } N \rightarrow \infty.
\end{align}

Hence, the limit $[\lim_{N\to\infty}f_N](\varphi) := \lim_{N \to \infty} \langle f_N, \varphi \rangle$, where $\varphi \in \mathcal{T}$ is a test function, defines a distribution in $\mathcal{T}'$, which agrees with $f$ as they have the same Fourier series coefficients.

\label{thm:filtered-TBP}
    Let $r\in\mathbb{R}, s\geq r$, $\alpha>0$ and let $f^{\alpha,s}$ denote the Tikhonov regularized solution corresponding to \eqref{eq:tikhonov} with data $g\in H^r(\mathbb{T}^2\times Q)$. Then
    \begin{equation}
        f^{\alpha,s}=\lim_{N\to\infty} ((g_N -E_N) * p_{\alpha}^{\,s-r})
    \quad \text{in } H^{2s-r}(\mathbb{T}^2),
    \end{equation}
    where $g_N$ and $E_N$ are defined as in \eqref{eq:g_N_TBP} and \eqref{eq:errorE}, and
    \begin{equation}
        p_{\alpha}^{s-r}(x)=\sum_{k\in\mathbb{Z}^2}\frac{1}{1+\alpha\langle k\rangle^{2(s-r)}}e^{2\pi i k\cdot x}.
    \end{equation}
    In particular, if $e\equiv 0$, then $f^{\alpha,s}=\lim_{N\rightarrow\infty}(g_N*p_\alpha^{s-r})$ in $H^{2s-r}(\mathbb{T}^2)$.

By \cite[Theorem 2]{IKR19}, the minimizer of \eqref{eq:tikhonov} is $f^{\alpha,s}=P_{\alpha}^{s-r}\mathcal{I}^*g$. 

    We next identify $P_{\alpha}^{s-r}$ as a convolution operator. By definition
    \begin{equation}
        \widehat{f^{\alpha,s}}(k) = \frac{1}{1+\alpha\langle k\rangle^{2(s-r)}}\widehat{\mathcal{I}^*g}(k) = \widehat{p_{\alpha}^{s-r}}(k)\,\widehat{\mathcal{I}^*g}(k).
    \end{equation}

    Now, the convolution theorem implies
    \begin{equation}
        f^{\alpha,s} = \mathcal{I}^*g * p_{\alpha}^{s-r}.
    \end{equation}

    Next, we show that $g_N-E_N\rightarrow\mathcal{I}^*g$ in $H^r(\mathbb{T}^2)$. On the Fourier side, when $k\neq0$, we can split directions according to whether they are orthogonal, which gives
    \begin{equation}
\hat{g}_N(k)=\sum_{v\in Q_N, k\cdot v= 0} \hat{g}(k,v) + \hat{E}_N(k).
    \end{equation}

    The only direction orthogonal to $k$ in $Q$ is $\hat{k}^\perp$ which is in $Q_N$ whenever $N\geq |k|_{\infty}$. Now by \eqref{eq:adjoint}, we have, $(g_N-E_N)^{\wedge}(k)=\hat{g}(k,\hat{k}^\perp)=\widehat{\mathcal{I}^*g}(k)$ for $N\geq|k|_{\infty}$, and $(g_N-E_N)^{\wedge}(k)\in\{0,\widehat{\mathcal{I}^*g}(k)\}$ for all $N$. For $k=0$, we have $\hat{E}_N(0)=0$, and all averages of $g$ equal $\hat{g}(0,0),$ so $(g_N-E_N)^{\wedge}(0)=\hat{g}(0,0)=\widehat{\mathcal{I}^*g}(0)$. Therefore 
    \begin{equation}
        \| g_N - E_N- \mathcal{I}^*g \|^2_{H^r(\mathbb{T}^2)} \leq \sum_{k\in \mathbb{Z}^2\setminus \mathbb{Z}_N^2} \langle k \rangle^{2r} |\widehat{\mathcal{I}^*g}(k)|^2 \rightarrow 0 \quad \text{as }\,N \rightarrow\infty,
    \end{equation}
    since $\mathcal{I}^*g\in H^r(\mathbb{T}^2)$. In particular $g_N-E_N\rightarrow \mathcal{I}^*g$ in $H^r(\mathbb{T}^2)$.

    The filter multiplies the $k$'th Fourier coefficient by $(1+\alpha\langle k \rangle^{2(s-r)})^{-1}$, and
    \begin{equation}
    \label{eq:filterupperbound}
        \frac{\langle k \rangle^{2(s-r)}}{1+\alpha \langle k \rangle^{2(s-r)}}\leq \frac{1}{\alpha}, \qquad k\in\mathbb{Z}^2.
    \end{equation}
    Therefore, for every $h\in H^{r}(\mathbb{T}^2)$, one has $\| h*p_{\alpha}^{s-r} \|_{H^{2s-r}(\mathbb{T}^2)}\leq\alpha^{-1}\| h\|_{H^r(\mathbb{T}^2)}$. With $h=g_N-E_N-\mathcal{I}^*g$ and $f^{\alpha,s}=\mathcal{I}^*g*p_{\alpha}^{s-r}$, this gives
    \begin{equation}
        \| (g_N-E_N)*p_{\alpha}^{s-r}-f^{\alpha,s} \|_{H^{2s-r}(\mathbb{T}^2)}\leq \frac{1}{\alpha}\| g_N-E_N-\mathcal{I}^*g \|_{H^r(\mathbb{T}^2)}\rightarrow0, \quad \text{as } N\rightarrow\infty.
    \end{equation}
    If $e\equiv 0$, then $E_N=0$ for every $N$, which gives the last claim and thus concludes the proof.

\label{cor:error_estimate} Under the assumptions of Theorem \ref{thm:filtered-TBP}, we have
\begin{equation}
    \lim_{N\rightarrow\infty}( \| f^{\alpha,s} - g_N * p_\alpha^{s-r} \|_{H^{2s-r}(\mathbb{T}^2)}- \| E_N * p_\alpha^{s-r} \|_{H^{2s-r}(\mathbb{T}^2)})=0.
\end{equation}

By linearity, $g_N*p^{s-r}_\alpha - f^{\alpha,s} = E_N*p_{\alpha}^{s-r} + h_N$, where $h_N:=(g_N-E_N)*p_\alpha^{s-r} - f^{\alpha,s}$. By Theorem \ref{thm:filtered-TBP}, $h_N\rightarrow0$ in $H^{2s-r}(\mathbb{T}^2)$. Since $E_N\in H^{r}(\mathbb{T}^2)$, by \eqref{eq:filterupperbound}, $E_N*p_{\alpha}^{s-r}\in H^{2s-r}(\mathbb{T}^2)$. By the reverse triangle inequality, we have
    \begin{equation}
        \left| \| f^{\alpha,s} - g_N * p_\alpha^{s-r} \|_{H^{2s-r}(\mathbb{T}^2)} -   \| E_N * p_\alpha^{s-r} \|_{H^{2s-r}(\mathbb{T}^2)}\right| \leq \| h_N \|_{H^{2s-r}(\mathbb{T}^2)}\rightarrow0,
    \end{equation}
    which concludes the proof.

\label{cor:noisydata} Let $r\in\mathbb{R}$, $s\geq r$, $\alpha>0$ and $f\in H^r(\mathbb{T}^2)$. Suppose that $g=\mathcal{I}f + \eta$, where $\eta\in H^r(\mathbb{T}^2\times Q)$. Then $e$ and $E_N$ depend only on $\eta$. If $\eta$ is constant along geodesics, then 
\begin{equation}
\lim_{N\rightarrow\infty} g_N*p_\alpha^{s-r} = P^{s-r}_\alpha f + P^{s-r}_\alpha \mathcal{I}^*\eta \quad \text{in }H^{2s-r}(\mathbb{T}^2),
\end{equation}
and
\begin{equation}
    \| P^{s-r}_\alpha \mathcal{I}^*\eta \|_{H^{r}(\mathbb{T}^2)} \leq \| \eta \|_{H^r(\mathbb{T}^2 \times Q)}, \qquad \| P^{s-r}_\alpha \mathcal{I}^*\eta \|_{H^{2s-r}(\mathbb{T}^2)} \leq \frac{1}{\alpha} \| \eta \|_{H^{r}(\mathbb{T}^2 \times Q)}.
\end{equation}

\label{prop:zeromode}
    Let $g=If + \eta$ be a noisy data corresponding to some $f \in \mathcal{T}'$ with an error term $\eta: \mathbb{T}^2 \times Q \to \mathbb{R}$. Suppose that the errors $\mathcal{E}_v := \bar{g}_v-\hat{f}(0),$ for $v\in Q_N$, are real-valued random variables with zero mean, with variance at most $C \geq 0$, and are pairwise uncorrelated. Then the zero mode of the filtered torus backprojection is an unbiased estimator of $\hat{f}(0)/(1+\alpha)$. In particular,
    \begin{equation}
        \mathbb{E}\widehat{f^{\alpha,s}_{\mathrm{TBP}}}(0)=\frac{\hat{f}(0)}{1+\alpha},
    \end{equation}
    and its mean squared error satisfies
    \begin{equation}
    \mathbb{E}\left|\widehat{f^{\alpha,s}_{\mathrm{TBP}}}(0)-\frac{\hat{f}(0)}{1+\alpha}\right|^2\leq \frac{C}{(1+\alpha)^2|Q_N|}.
    \end{equation}

The constant terms in \eqref{eq:f_TBP} give $\widehat{f_{\mathrm{TBP}}}(0)=\frac{1}{|Q_N|}\sum_{v\in Q_N}\bar{g}_v$, and since $\langle 0\rangle=1$, for the filtered case the zero mode is multiplied by $(1+\alpha)^{-1}$. Thus
    \begin{equation}
        \widehat{f^{\alpha,s}_{\mathrm{TBP}}}(0)-\frac{\hat{f}(0)}{1+\alpha} = \frac{1}{(1+\alpha)|Q_N|}\sum_{v\in Q_N}(\bar{g}_v-\hat{f}(0)).
    \end{equation}
    Taking expectations and using that the errors have zero mean gives the unbiasedness. Since the errors have zero mean and are pairwise uncorrelated, $\mathbb{E}(\bar{g}_v - \hat{f}(0))\overline{(\bar{g}_w-\hat{f}(0))}=0$ for $v\neq w$, $v,w \in Q_N$, and since $\mathbb{E}|\bar{g}_v - \hat{f}(0)|^2\leq C$, we get
    \begin{equation}
        \mathbb{E}\left| \ \sum_{v\in Q_N}(\bar{g}_v-\hat{f}(0)) \right|^2
 =  \sum_{v\in Q_N}\mathbb{E} \left| \bar{g}_v-\hat{f}(0)\right|^2 \leq C|Q_N|.   \end{equation}
 Now dividing by $(1+\alpha)^2|Q_N|^2$ gives the mean squared error estimate.
